const config = msg.payload

if (!config.client_specific.api_key) {
    return null
}

const user = JSON.parse(
        Buffer.from(config.client_specific.api_key.split(".")[1], "base64").toString("utf-8")
    );
msg.group_id = user.group.id
return msg;

const utils    = global.get("utils");                                                                                                                          
const base_url = global.get("parat_bridge").base_urls.rayvn;                                                                                                   
const api_key  = msg.payload.client_specific.api_key;                                                                                                          
const group_id = msg.group_id;                                                                                                                                 

const headers = {                                                                                                                                              
    "Authorization": "Bearer " + api_key,                                                                                                                      
    "Content-Type":  "application/json"                                                                                                                        
};                                                                                                                                                             

function request(method, path, body) {                                                                                                                         
    return new Promise((resolve, reject) => {
        const url     = new URL(base_url + path);
        const payload = body ? JSON.stringify(body) : null;                                                                                                    
        const req     = https.request({
            hostname: url.hostname,                                                                                                                            
            path:     url.pathname,
            method,
            headers:  { ...headers, "Content-Length": payload ? Buffer.byteLength(payload) : 0 }
        }, res => {                   
            let data = "";                                                                                                                                     
            res.on("data", chunk => data += chunk);
            res.on("end", () => {                                                                                                                              
                try { resolve({ status: res.statusCode, data: JSON.parse(data) }); }
                catch (e) { resolve({ status: res.statusCode, data }); }
            });                                                                                                                                                
        });   
        req.on("error", reject);                                                                                                                               
        if (payload) req.write(payload);
        req.end();
    });                                                                                                                                                        
}                                     

(async () => {  
    try {
        const existing = (await request("GET", "/tags", null)).data;

        for (const [key, template] of Object.entries(utils.RAYVN_TAGS)) {                                                                                      
            const regex = new RegExp("^" + template.name + "$", "i");
            const match = existing.find(t => regex.test(t.name));                                                                                              
            const body  = { ...template, group: { id: group_id } };

            let resolved;
            if (match) {          
                resolved = (await request("POST", "/tags/" + match.id, body)).data;
                node.log("Tag updated: " + template.name + " (" + match.id + ")");                                                                             
            } else {                  
                resolved = (await request("POST", "/tags", body)).data;                                                                                        
                node.log("Tag created: " + template.name + " (" + resolved.id + ")");
            }                                                                                                                                                  

            msg.payload.client_specific.tags = msg.payload.client_specific.tags || {};
            msg.payload.client_specific.tags[key] = resolved;                                                                                                  
        }                         

        node.send(msg);                                                                                                                                        
    } catch (e) {
        node.error("POST tags failed: " + e.message, msg);                                                                                                     
    }           
})();                             

return null;
